// CSD_RATIONALE_BEGIN
// EOS-injection strategy for missing final-answer span.
//
// Primary failure (35/49): model writes a short intermediate span (e.g., <<n1 * c1 >>)
// then EOS before writing "The final answer is <<...>>". The evaluator extracts the last
// visible span as the answer, yielding a wrong intermediate value.
//
// Core fix: in the outside-span EOS handler, check generated text for "The final answer is".
// If not found AND budget permits (remaining > closeReserve + 1), call OpenConstrainedSpan
// to force-open a new span. The model's context then includes all prior intermediate spans
// and must generate the aggregated final expression inside the constrained parser.
//
// Secondary fixes:
// (a) Anti-loop guard: if |currentConstrainedOut| > 50, expression is in a repetition loop;
//     force-close with CloseSpanWithinBudget using remaining budget.
// (b) Larger closeReserve=150 (from attempt 3) for better syntax rate.
// (c) SafeRepetitionPenaltyStep(4.0) (from best attempt 2) to suppress token-level loops.
// (d) Guidance: emphasize that final <<>> must be the COMPLETE aggregated formula,
//     combining ALL quantities from the problem statement.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 – parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   (closeReserve branch, anti-loop branch):
//     CloseSpanWithinBudget postcondition: insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
//   (outside-span EOS, forced-open path):
//     OpenConstrainedSpan sets insideConstrainedOut := true, currentConstrainedOut := [].
//     parser.IsValidPrefix([]) holds by method precondition (parser.IsValidPrefix([])). ✓
//
//   (outside-span EOS, break path):
//     insideConstrainedOut unchanged (false) → implication vacuously true. ✓
//
//   (outside-span non-EOS, "<<" detected):
//     currentConstrainedOut := []; parser.IsValidPrefix([]) by precondition. ✓
//
//   (IsCompletePrefix branch):
//     CloseConstrainedSpan sets insideConstrainedOut := false → vacuously true. ✓
//
//   (normal constrained step):
//     SafeRepetitionPenaltyStep hard-masks to parser-valid tokens; AppendConstrainedToken
//     preserves parser.IsValidPrefix(currentOut) by its postcondition. ✓
//
//   (final cleanup): same as closeReserve branch. ✓
//
// Invariant 2 – progress: |generated| <= |generatedPrefix| + steps
//
//   (closeReserve and anti-loop): CloseSpanWithinBudget(remaining) postcondition gives
//     |cg| <= |generated| + remaining <= |generatedPrefix| + old_steps + (maxSteps - old_steps)
//     = |generatedPrefix| + maxSteps. After steps := maxSteps: |generated| <= |generatedPrefix| + steps. ✓
//
//   (outside-span, non-EOS): steps + 1; at most 1 token appended to generated. ✓
//
//   (outside-span, EOS, forced-open): steps + 2 total (1 for EOS step + 1 for OpenConstrainedSpan).
//     OpenConstrainedSpan appends exactly 1 token ("<<"). |generated| grows by 1, steps by 2;
//     inductive hypothesis gives |generated| + 1 <= |generatedPrefix| + (old_steps + 2). ✓
//
//   (IsCompletePrefix): steps + 1; CloseConstrainedSpan appends at most one ">>" token. ✓
//
//   (constrained step, non-EOS): steps + 1; AppendConstrainedToken appends exactly 1 token. ✓
//   (constrained step, EOS): steps + 1; break with no append. ✓
//
//   (final cleanup): same argument as closeReserve branch. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step using the symbolic variable names from the problem statement. " +
  "Show each sub-computation by wrapping each sub-expression in << >>. " +
  "ALWAYS end your response with exactly: The final answer is <<complete expression>>. " +
  "The final << >> MUST contain ONE complete formula that directly answers the question, " +
  "combining ALL relevant quantities—never stop at an intermediate sub-result. " +
  "Inside << >>: use only the variable names from the problem, numbers, " +
  "+, -, *, /, //, %, (), int(). " +
  "Use / for real division, // for integer floor division, int() to convert to integer. " +
  "Never substitute numeric values for symbolic variable names.");

var closeReserve: nat := 150;
var maxConstrainedLen: nat := 50;
var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var remaining: nat := maxSteps - steps;

  if insideConstrainedOut && remaining <= closeReserve {
    // Budget running low inside a span: force-close with dead-end-aware helper
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
    break;
  } else if insideConstrainedOut && |currentConstrainedOut| > maxConstrainedLen {
    // Anti-loop guard: constrained expression too long, likely in a repetition loop
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
    break;
  } else if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      // Check whether model has written a final answer
      var genStr := CSDHelpers.PrefixToString(generated);
      var finalCount := CSDHelpers.CountSubstring(genStr, "The final answer is");
      // Force-open a final answer span if: no final answer yet AND enough budget remains
      // Need remaining > closeReserve + 1 so that after open (costs 1) we still have
      // remaining - 2 >= closeReserve steps for constrained content and forced close
      if finalCount == 0 && remaining > closeReserve + 1 {
        var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
        generated := og;
        insideConstrainedOut := oi;
        currentConstrainedOut := oc;
        steps := steps + 1;
      } else {
        break;
      }
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    // Inside span and parser accepts it as complete: close immediately
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    // Inside span, not complete, budget ample: generate next constrained token
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.SafeRepetitionPenaltyStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, generated, 4.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Final cleanup: close any still-open constrained span with remaining budget
if insideConstrainedOut && steps < maxSteps {
  var remaining2: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining2
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

